# Deze onderwerpen hebben geen aantoonbare algemene gebruikersroute in het lokale
# handleidingcontract. Bewaren voor conservatieve dekking, niet als actieve functies tonen.
OPTIONAL = re.compile(r'code_(?:workspace|environment)|stateful_code|run_code|langfuse|skills?|project_|background_task|subagent|wakeup_|steer_|schedule|trace_|ptc_|com_ui_memory_|passkey|2fa|two_factor|backup_codes|email_change|balance_auto_refill|insights|mcp_app|ui_resource|SAML_CERT|^Invalid (?:endpoint|file|interface|role) context$', re.I)
LABEL = re.compile(r'(?:_title|_label|_prefix|_subject|_hover|_suggestion|_description|_retrying|_countdown|_count_failed_(?:one|other)|_status_(?:failed|error)|_summary_errors|_failed_n_of_n|_failed_one_of_(?:n|one))$|token_balance_(?:currency|generation|generations|hidden|prompt)$|error_window_|error_details_|error_retry|agents_error_retry|error_context_next_steps|feedback_tag|show_error|show_failed|agents_error_search_title|agents_error_not_found_message|error_agent_contact_email|com_ui_error_details$', re.I)


def explain(key, message, source, rules):
    """Return title, meaning, safe step, admin step, disposition and rationale."""
    low = key + ' ' + message
    optional = bool(OPTIONAL.search(key))
    label = bool(LABEL.search(key)) or key in {'GET', 'POST', 'timeout_ms', 'fault', 'ENOENT'}
    noise = source == 'retired-catalog' or bool(re.search(r'throw new|return res\.|\)\)|^<|data-govchat-manual|\|\||Processing error in .*Controller', key.strip()))
    if noise:
        return ('Historische bronvermelding, geen foutdiagnose', 'Dit is een eerder conservatief geïnventariseerde bronstring of extractieruis, geen stabiele gebruikersfoutcode. De oorspronkelijke herkenning blijft behouden voor cataloguscompatibiliteit.', 'Zoek de daadwerkelijk zichtbare melding of code. Baseer geen herstelactie op een codefragment of interne logtekst.', 'Controleer de actuele callsite en foutvorm; deze bijlage maakt een interne string niet bereikbaar voor gebruikers.', 'appendix', 'Historische string/extractieruis; geen bevestigde gebruikersmelding.')
    if label:
        shown = message or key
        return ('Toelichting bij een schermlabel', f'“{shown}” is een label, status of toelichting bij een andere melding. Het beschrijft op zichzelf geen afzonderlijke storing; parameters zoals {{{{0}}}} worden door de toepassing ingevuld, niet door deze handleiding.', 'Lees de bijbehorende volledige fout en zoek de concrete code. Een status als “mislukt” zegt niet welke bewerking wel is uitgevoerd.', 'Controleer de samengestelde UI-melding en de concrete errorcode. Dit label is geen eigen diagnose.', 'appendix', 'Label/status/aanvullende tekst, geen zelfstandige fout.')
    for pattern, title, meaning, step in RECIPES:
        if re.search(pattern, key, re.I) or re.search(pattern, low, re.I):
            if optional:
                meaning += ' Deze optionele productfunctie is niet als algemeen beschikbare route aangetoond in dit lokale contract.'
            return (title, meaning, step, 'Controleer de concrete callsite, effectieve functieconfiguratie en rechten. Onderzoek serverdetails alleen via de bevoegde veilige beheerroute.', 'appendix' if optional else 'error', 'Optionele functie niet aangetoond.' if optional else 'Taakgerichte foutfamilie; code alleen bewijst geen oorzaak.')
    for pattern, meaning, step, admin in rules:
        if re.search(pattern, low, re.I):
            if optional:
                meaning += ' Deze optionele productfunctie is niet als algemeen beschikbare route aangetoond in dit lokale contract.'
            return ('Melding bij ' + surface(key), meaning, step, admin, 'appendix' if optional else 'error', 'Optionele functie niet aangetoond.' if optional else 'Specifieke begrenzing of foutfamilie.')
    # Geen verzonnen diagnose: een niet-gemapte string krijgt een eerlijk begrensde
    # naslaguitleg, nooit 352 keer dezelfde vermeende foutverklaring in de hoofdcatalogus.
    return ('Naslag: ' + surface(key), f'De bron bevat “{message or key}”, maar de oorzaak en algemene bereikbaarheid van deze specifieke melding zijn niet vastgesteld. Dit is geen bewijs dat de functie voor jou aan staat.', 'Noteer de zichtbare actie en controleer eerst of het resultaat al bestaat. Zoek daarna een concretere code of het gewone onderwerp in de handleiding. Herhaal geen verwijder-, deel- of publicatieactie blind.', 'Beoordeel callsite, endpointcontract en actuele rechten voordat deze naslagmelding als gebruikersdiagnose wordt aangeboden.', 'appendix', 'Geen specifieke diagnose/bereikbaarheid onderbouwd; expliciete naslagfallback.')


def surface(key):
    for pattern, name in [(r'prompt|group', 'de promptbibliotheek'), (r'auth|login|oauth|openid|password|token', 'aanmelden en rechten'), (r'file|upload|document|extract', 'documenten en bestanden'), (r'agent|tool|mcp', 'apps en agenttools'), (r'manual|revision|passage|publish', 'de handleiding'), (r'chat|convo|message', 'het gesprek')]:
        if re.search(pattern, key, re.I): return name
    return 'de gevraagde productactie'
